const MANIFEST = {
  "type": "Games.WhackAMole",
  "description": "Interactive whack-a-mole game with score tracking, timer, and smooth animations",
  "editorElement": {
    "selector": ".whack-a-mole",
    "displayName": "Whack-a-Mole Game",
    "archetype": "container",
    "data": {
      "title": { "dataType": "text", "displayName": "Title", "defaultValue": "Whack-a-Mole", "group": "Content" },
      "gameDuration": { "dataType": "select", "displayName": "Game Duration (seconds)", "defaultValue": "30", "options": ["15", "30", "45", "60"], "group": "Content" },
      "moleSpeed": { "dataType": "select", "displayName": "Mole Speed (ms)", "defaultValue": "800", "options": ["600", "800", "1000", "1200"], "group": "Content" },
      "gridSize": { "dataType": "select", "displayName": "Grid Size", "defaultValue": "3x3", "options": ["3x3", "4x4"], "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background Color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "holeBackground": { "dataType": "color", "displayName": "Hole Background", "defaultValue": "#F8F9FA", "group": "Colors" },
      "moleColor": { "dataType": "color", "displayName": "Mole Color", "defaultValue": "#495057", "group": "Colors" },
      "textColor": { "dataType": "color", "displayName": "Text Color", "defaultValue": "#212529", "group": "Colors" },
      "secondaryTextColor": { "dataType": "color", "displayName": "Secondary Text Color", "defaultValue": "#495057", "group": "Colors" },
      "borderColor": { "dataType": "color", "displayName": "Border Color", "defaultValue": "#E9ECEF", "group": "Colors" },
      "accentColor": { "dataType": "color", "displayName": "Accent Color", "defaultValue": "#495057", "group": "Colors" },
      "buttonHoverColor": { "dataType": "color", "displayName": "Button Hover Color", "defaultValue": "#343A40", "group": "Colors" },
      "fontSize": { "dataType": "number", "displayName": "Base Font Size (px)", "defaultValue": 15, "group": "Typography" },
      "fontWeight": { "dataType": "select", "displayName": "Font Weight", "defaultValue": "400", "options": ["300", "400", "500"], "group": "Typography" },
      "titleFontSize": { "dataType": "number", "displayName": "Title Font Size (px)", "defaultValue": 28, "group": "Typography" },
      "cornerRadius": { "dataType": "select", "displayName": "Corner Radius", "defaultValue": "12px", "options": ["8px", "10px", "12px", "14px", "16px"], "group": "Layout" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

function Component({ config = {} }) {
  const [gameState, setGameState] = React.useState('idle');
  const [score, setScore] = React.useState(0);
  const [timeLeft, setTimeLeft] = React.useState(parseInt(config?.gameDuration || '30'));
  const [moles, setMoles] = React.useState([]);
  const [highScore, setHighScore] = React.useState(0);

  const gridSize = config?.gridSize || '3x3';
  const gridCount = gridSize === '3x3' ? 9 : 16;
  const moleSpeed = parseInt(config?.moleSpeed || '800');
  const gameDuration = parseInt(config?.gameDuration || '30');

  const startGame = () => {
    setGameState('playing');
    setScore(0);
    setTimeLeft(gameDuration);
    setMoles([]);
  };

  const endGame = () => {
    setGameState('finished');
    if (score > highScore) setHighScore(score);
  };

  React.useEffect(() => {
    if (gameState !== 'playing') return;

    const timer = setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 1) {
          endGame();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [gameState]);

  React.useEffect(() => {
    if (gameState !== 'playing') return;

    const moleInterval = setInterval(() => {
      const randomHole = Math.floor(Math.random() * gridCount);
      if (!moles.includes(randomHole)) {
        setMoles(prev => [...prev, randomHole]);
        setTimeout(() => {
          setMoles(prev => prev.filter(m => m !== randomHole));
        }, moleSpeed);
      }
    }, moleSpeed * 0.7);

    return () => clearInterval(moleInterval);
  }, [gameState, moles, moleSpeed, gridCount]);

  const handleWhack = (holeIndex) => {
    if (moles.includes(holeIndex)) {
      setScore(s => s + 1);
      setMoles(prev => prev.filter(m => m !== holeIndex));
    }
  };

  const prefersReducedMotion = typeof window !== 'undefined' ? window.matchMedia('(prefers-reduced-motion: reduce)').matches : false;

  return (
    <div className="whack-a-mole" style={{ backgroundColor: config?.backgroundColor || '#FFFFFF', color: config?.textColor || '#212529', padding: '24px', fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif', fontSize: `${config?.fontSize || 15}px`, fontWeight: config?.fontWeight || '400', maxWidth: '600px', margin: '0 auto', minHeight: '500px' }}>
      <div style={{ marginBottom: '32px', textAlign: 'center' }}>
        <h1 style={{ fontSize: `${config?.titleFontSize || 28}px`, fontWeight: '500', margin: '0 0 8px 0', letterSpacing: '-0.02em' }}>{config?.title || 'Whack-a-Mole'}</h1>
        <div style={{ color: config?.secondaryTextColor || '#495057', fontSize: `${(config?.fontSize || 15) * 0.93}px` }}>Test your reflexes!</div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '16px', marginBottom: '24px' }}>
        <div style={{ backgroundColor: config?.holeBackground || '#F8F9FA', padding: '16px', borderRadius: config?.cornerRadius || '12px', border: `1px solid ${config?.borderColor || '#E9ECEF'}`, textAlign: 'center' }}>
          <div style={{ fontSize: `${(config?.fontSize || 15) * 0.8}px`, color: config?.secondaryTextColor || '#495057', marginBottom: '4px' }}>Score</div>
          <div style={{ fontSize: `${(config?.fontSize || 15) * 1.6}px`, fontWeight: '500' }}>{score}</div>
        </div>
        <div style={{ backgroundColor: config?.holeBackground || '#F8F9FA', padding: '16px', borderRadius: config?.cornerRadius || '12px', border: `1px solid ${config?.borderColor || '#E9ECEF'}`, textAlign: 'center' }}>
          <div style={{ fontSize: `${(config?.fontSize || 15) * 0.8}px`, color: config?.secondaryTextColor || '#495057', marginBottom: '4px' }}>Time</div>
          <div style={{ fontSize: `${(config?.fontSize || 15) * 1.6}px`, fontWeight: '500' }}>{timeLeft}s</div>
        </div>
        <div style={{ backgroundColor: config?.holeBackground || '#F8F9FA', padding: '16px', borderRadius: config?.cornerRadius || '12px', border: `1px solid ${config?.borderColor || '#E9ECEF'}`, textAlign: 'center' }}>
          <div style={{ fontSize: `${(config?.fontSize || 15) * 0.8}px`, color: config?.secondaryTextColor || '#495057', marginBottom: '4px' }}>Best</div>
          <div style={{ fontSize: `${(config?.fontSize || 15) * 1.6}px`, fontWeight: '500' }}>{highScore}</div>
        </div>
      </div>

      {gameState === 'idle' && (
        <div style={{ textAlign: 'center', padding: '48px 24px' }}>
          <button onClick={startGame} style={{ padding: '14px 48px', backgroundColor: config?.accentColor || '#495057', color: '#FFFFFF', border: 'none', borderRadius: config?.cornerRadius || '12px', cursor: 'pointer', fontSize: `${(config?.fontSize || 15) * 1.07}px`, fontWeight: '500', transition: prefersReducedMotion ? 'none' : 'background-color 200ms ease-out' }} onMouseEnter={(e) => e.target.style.backgroundColor = config?.buttonHoverColor || '#343A40'} onMouseLeave={(e) => e.target.style.backgroundColor = config?.accentColor || '#495057'}>Start Game</button>
        </div>
      )}

      {gameState === 'playing' && (
        <div style={{ display: 'grid', gridTemplateColumns: gridSize === '3x3' ? 'repeat(3, 1fr)' : 'repeat(4, 1fr)', gap: '12px', marginBottom: '24px' }}>
          {Array(gridCount).fill(0).map((_, index) => (
            <button key={index} onClick={() => handleWhack(index)} style={{ aspectRatio: '1', backgroundColor: config?.holeBackground || '#F8F9FA', border: `2px solid ${config?.borderColor || '#E9ECEF'}`, borderRadius: config?.cornerRadius || '12px', cursor: 'pointer', position: 'relative', overflow: 'hidden', transition: prefersReducedMotion ? 'none' : 'all 150ms ease-out' }} onMouseEnter={(e) => e.currentTarget.style.backgroundColor = config?.borderColor || '#E9ECEF'} onMouseLeave={(e) => e.currentTarget.style.backgroundColor = config?.holeBackground || '#F8F9FA'}>
              {moles.includes(index) && (
                <div style={{ position: 'absolute', bottom: '10%', left: '50%', transform: 'translateX(-50%)', width: '70%', height: '70%', backgroundColor: config?.moleColor || '#495057', borderRadius: '50% 50% 40% 40%', opacity: prefersReducedMotion ? 1 : 0, animation: prefersReducedMotion ? 'none' : 'moleAppear 200ms ease-out forwards' }} />
              )}
            </button>
          ))}
        </div>
      )}

      {gameState === 'finished' && (
        <div style={{ textAlign: 'center', padding: '48px 24px', backgroundColor: config?.holeBackground || '#F8F9FA', borderRadius: config?.cornerRadius || '12px', border: `1px solid ${config?.borderColor || '#E9ECEF'}` }}>
          <div style={{ fontSize: `${(config?.fontSize || 15) * 1.6}px`, fontWeight: '500', marginBottom: '16px' }}>Game Over!</div>
          <div style={{ fontSize: `${(config?.fontSize || 15) * 1.2}px`, marginBottom: '8px' }}>Final Score: <strong>{score}</strong></div>
          {score === highScore && score > 0 && (
            <div style={{ color: config?.accentColor || '#495057', marginBottom: '24px' }}>🎉 New High Score!</div>
          )}
          <button onClick={startGame} style={{ padding: '12px 40px', backgroundColor: config?.accentColor || '#495057', color: '#FFFFFF', border: 'none', borderRadius: config?.cornerRadius || '12px', cursor: 'pointer', fontSize: `${config?.fontSize || 15}px`, fontWeight: '500', transition: prefersReducedMotion ? 'none' : 'background-color 200ms ease-out' }} onMouseEnter={(e) => e.target.style.backgroundColor = config?.buttonHoverColor || '#343A40'} onMouseLeave={(e) => e.target.style.backgroundColor = config?.accentColor || '#495057'}>Play Again</button>
        </div>
      )}

      <style>{`
        @keyframes moleAppear {
          from {
            opacity: 0;
            transform: translateX(-50%) translateY(20px);
          }
          to {
            opacity: 1;
            transform: translateX(-50%) translateY(0);
          }
        }
      `}</style>
    </div>
  );
}

